CREATE TABLE `patients` (
  `id` int NOT NULL AUTO_INCREMENT,
  `firstName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lastName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `identificationNumber` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateOfBirth` date DEFAULT NULL,
  `gender` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `medicalHistory` text COLLATE utf8mb4_unicode_ci,
  `allergies` text COLLATE utf8mb4_unicode_ci,
  `emergencyContact` text COLLATE utf8mb4_unicode_ci,
  `emergencyPhone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergencyRelation` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `medicalObservations` text COLLATE utf8mb4_unicode_ci,
  `specialNeeds` text COLLATE utf8mb4_unicode_ci,
  `generalObservations` text COLLATE utf8mb4_unicode_ci,
  `medications` json DEFAULT NULL,
  `treatmentHistory` json DEFAULT NULL,
  `pendingTasks` json DEFAULT NULL,
  `isActive` tinyint NOT NULL DEFAULT '1',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
