INSERT INTO `patients` VALUES (1,'Juan','Pérez García','1234567890','1945-03-15','M','+593987654321','Av. Principal 123, Quito','Hipertensión arterial desde 2010. Cirugía de cadera en 2018.','Penicilina','María Pérez','+593987654322','Hija','Hipertensión controlada. Movilidad reducida.','Requiere asistencia para caminar. Dieta baja en sodio.','Paciente colaborador, buen estado de ánimo.','[{\"name\": \"Enalapril\", \"notes\": \"Tomar con alimentos\", \"dosage\": \"10mg\", \"frequency\": \"Cada 12 horas\", \"schedules\": \"08:00, 20:00\"}, {\"name\": \"Aspirina\", \"notes\": \"Después del desayuno\", \"dosage\": \"100mg\", \"frequency\": \"Cada 24 horas\", \"schedules\": \"08:00\"}]','[{\"date\": \"2024-12-01\", \"time\": \"10:30\", \"type\": \"Administración de Medicamento\", \"nurseName\": \"Ana García\", \"description\": \"Se administró Enalapril según prescripción médica.\"}, {\"date\": \"2024-12-01\", \"time\": \"14:00\", \"type\": \"Toma de Signos Vitales\", \"nurseName\": \"Ana García\", \"description\": \"Presión arterial: 130/85, Temperatura: 36.5°C, Frecuencia cardíaca: 75 lpm\"}]','[{\"type\": \"checkup\", \"title\": \"Control de presión arterial\", \"priority\": \"medium\", \"completed\": false, \"assignedTo\": \"Ana García\", \"description\": \"Monitoreo de presión arterial matutino\", \"scheduledDate\": \"2024-12-03T08:00\"}]',1,'2025-12-03 00:15:47.111736','2025-12-03 00:15:47.122512'),(2,'Rosa','Martínez Silva','0987654321','1950-07-22','F','+593976543210','Calle Flores 456, Guayaquil','Diabetes tipo 2. Alzheimer leve.','Ninguna conocida','Carlos Martínez','+593976543211','Hijo','Alzheimer en etapa inicial. Diabetes tipo 2 controlada con medicación.','Supervisión constante. Recordatorios para medicación. Dieta para diabéticos.','Requiere compañía. Buena disposición para actividades.','[{\"name\": \"Metformina\", \"notes\": \"Con las comidas principales\", \"dosage\": \"850mg\", \"frequency\": \"Cada 12 horas\", \"schedules\": \"08:00, 20:00\"}, {\"name\": \"Donepezilo\", \"notes\": \"Para memoria\", \"dosage\": \"5mg\", \"frequency\": \"Cada 24 horas\", \"schedules\": \"20:00\"}]','[{\"date\": \"2024-12-01\", \"time\": \"09:00\", \"type\": \"Glucometría\", \"nurseName\": \"María López\", \"description\": \"Nivel de glucosa: 125 mg/dL - Dentro de rango\"}, {\"date\": \"2024-12-01\", \"time\": \"12:30\", \"type\": \"Actividad Recreativa\", \"nurseName\": \"María López\", \"description\": \"Participó en terapia ocupacional - Realizó ejercicios de memoria\"}]','[{\"type\": \"analysis\", \"title\": \"Chequeo de glucosa\", \"priority\": \"high\", \"completed\": false, \"assignedTo\": \"María López\", \"description\": \"Glucometría en ayunas\", \"scheduledDate\": \"2024-12-03T07:00\"}, {\"type\": \"treatment\", \"title\": \"Ejercicios de memoria\", \"priority\": \"medium\", \"completed\": false, \"assignedTo\": \"María López\", \"description\": \"Sesión de estimulación cognitiva\", \"scheduledDate\": \"2024-12-03T15:00\"}]',1,'2025-12-03 00:15:47.111736','2025-12-03 00:15:47.122512'),(3,'Antonio','Rodríguez Gómez','1122334455','1938-11-10','M','+593965432109','Barrio Centro, Casa 789','Insuficiencia cardíaca. Marcapasos implantado en 2020.','Sulfonamidas','Elena Rodríguez','+593965432108','Esposa','Insuficiencia cardíaca compensada. Portador de marcapasos.','Reposo relativo. Evitar esfuerzos físicos. Control de peso diario.','Paciente tranquilo. Requiere entorno silencioso.','[{\"name\": \"Furosemida\", \"notes\": \"Diurético - Controlar peso\", \"dosage\": \"40mg\", \"frequency\": \"Cada 24 horas\", \"schedules\": \"08:00\"}, {\"name\": \"Carvedilol\", \"notes\": \"Para el corazón\", \"dosage\": \"6.25mg\", \"frequency\": \"Cada 12 horas\", \"schedules\": \"08:00, 20:00\"}]','[]','[]',1,'2025-12-03 00:15:47.111736','2025-12-03 00:15:47.122512'),(4,'Carmen','Fernández Torres','5566778899','1955-02-27','F','+593954321098','Urbanización Norte, Mz 12','Artrosis de rodilla bilateral. Cirugía de reemplazo de rodilla derecha pendiente.','Látex','Roberto Fernández','+593954321097','Esposo','Artrosis severa. Dolor crónico moderado.','Fisioterapia diaria. Asistencia para levantarse y caminar. Bastón o andador.','Paciente animada. Le gusta conversar.\n[3/12/2025, 11:06:12] le duele la cabeza al escuchar badbunny','\"[{\\\"name\\\":\\\"Ibuprofeno\\\",\\\"notes\\\":\\\"Solo si hay dolor\\\",\\\"dosage\\\":\\\"600mg\\\",\\\"frequency\\\":\\\"Cada 8 horas\\\",\\\"schedules\\\":\\\"08:00, 16:00, 00:00\\\"},{\\\"name\\\":\\\"Paracetamol\\\",\\\"notes\\\":\\\"Alternado con Ibuprofeno\\\",\\\"dosage\\\":\\\"500mg\\\",\\\"frequency\\\":\\\"Cada 6 horas PRN\\\",\\\"schedules\\\":\\\"Según necesidad\\\"}]\"','\"[]\"','\"[{\\\"type\\\":\\\"treatment\\\",\\\"title\\\":\\\"Fisioterapia de rodilla\\\",\\\"priority\\\":\\\"high\\\",\\\"completed\\\":false,\\\"assignedTo\\\":\\\"Lucía Martínez\\\",\\\"description\\\":\\\"Ejercicios de movilidad y fortalecimiento\\\",\\\"scheduledDate\\\":\\\"2024-12-03T10:00\\\"}]\"',1,'2025-12-03 00:15:47.111736','2025-12-03 11:06:12.000000'),(5,'Manuel','Sánchez Ruiz','9988776655','1960-09-05','M','+593943210987','Sector Sur, Calle Larga 321','EPOC (Enfermedad Pulmonar Obstructiva Crónica). Ex-fumador.','Ninguna','Laura Sánchez','+593943210986','Hija','EPOC moderado. Requiere oxigenoterapia nocturna.','Oxígeno 2 litros por minuto durante el sueño. Nebulizaciones según necesidad.','Paciente cooperativo. Ansioso por mejorar.','[{\"name\": \"Salbutamol\", \"notes\": \"Inhalador - Enjuagar boca después\", \"dosage\": \"2 puff\", \"frequency\": \"Cada 6 horas\", \"schedules\": \"06:00, 12:00, 18:00, 00:00\"}, {\"name\": \"Prednisona\", \"notes\": \"Con el desayuno\", \"dosage\": \"20mg\", \"frequency\": \"Cada 24 horas\", \"schedules\": \"08:00\"}]','[]','[]',1,'2025-12-03 00:15:47.111736','2025-12-03 00:15:47.122512'),(6,'Elena','Torres Jiménez','4433221100','1948-12-18','F','+593932109876','Parroquia Este, Av. Central','Osteoporosis. Fractura de cadera 2023.','Mariscos','Mi